using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class Candidate360Page:UserControl{ComboBox candidates;Panel body;public Candidate360Page(){BackColor=Theme.Background;Padding=new Padding(10);var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};top.Controls.Add(Ui.Label(L.Fa?"پروفایل ۳۶۰ کارجو":"Candidate 360",17,true));candidates=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};var t=Database.Query("SELECT Id,FullName FROM Candidates ORDER BY FullName");candidates.DataSource=t;candidates.DisplayMember="FullName";candidates.ValueMember="Id";candidates.SelectedIndexChanged+=(s,e)=>LoadCandidate();top.Controls.Add(candidates);Controls.Add(top);body=new Panel{Dock=DockStyle.Fill,AutoScroll=true};Controls.Add(body);body.BringToFront();if(t.Rows.Count>0)LoadCandidate();}void LoadCandidate(){if(candidates.SelectedValue==null||candidates.SelectedValue is System.Data.DataRowView)return;int id=Convert.ToInt32(candidates.SelectedValue);body.Controls.Clear();var profile=Ui.Card();profile.Dock=DockStyle.Top;profile.Height=150;var p=Database.Query("SELECT TOP 1 FullName,Email,Mobile,City,Education,PrimarySkill,ExperienceYears,Status,Summary FROM Candidates WHERE Id=@id",new SqlParameter("@id",id));if(p.Rows.Count>0){var r=p.Rows[0];var l=Ui.Label(Convert.ToString(r["FullName"])+"\n"+Convert.ToString(r["PrimarySkill"])+"  •  "+r["ExperienceYears"]+" yrs\n"+Convert.ToString(r["Email"])+"  |  "+Convert.ToString(r["Mobile"])+"\n"+Convert.ToString(r["Summary"]),12,true);l.Dock=DockStyle.Fill;l.AutoSize=false;profile.Controls.Add(l);}body.Controls.Add(profile);AddGrid(L.Fa?"مهارت‌ها":"Skills","SELECT Skill,Level,Years FROM CandidateSkills WHERE CandidateId=@id",id);AddGrid(L.Fa?"فرآیند استخدام":"Recruitment journey","SELECT j.Title,a.Stage,a.Score,a.AppliedAt FROM Applications a JOIN Jobs j ON j.Id=a.JobId WHERE a.CandidateId=@id ORDER BY a.Id DESC",id);AddGrid(L.Fa?"یادداشت‌ها":"Notes","SELECT Note,CreatedAt FROM CandidateNotes WHERE CandidateId=@id ORDER BY Id DESC",id);}void AddGrid(string title,string sql,int id){var card=Ui.Card();card.Dock=DockStyle.Top;card.Height=210;card.Padding=new Padding(10);var lab=Ui.Label(title,12,true);lab.Dock=DockStyle.Top;lab.Height=32;var g=Ui.Grid();g.DataSource=Database.Query(sql,new SqlParameter("@id",id));card.Controls.Add(g);card.Controls.Add(lab);body.Controls.Add(card);card.BringToFront();}}
}
